"""Fixed Python object primitives for the native machine-plan continuation.

HIA emits and executes the complete control/literal program.  This module does
not walk Core, classify instructions, calculate intervals, choose a branch, or
invoke a retained plan body.  A frame services one exact issued primitive at a
time, after a separate native claim, and acknowledges its actual outcome.
"""
from __future__ import annotations

import builtins
from collections import Counter
import ctypes
from dataclasses import dataclass
from functools import partial
import itertools
import operator
import struct
import sys

from .hia_exception_delivery import ExceptionDelivery
from .hia_json_preflight_native import NativeHiaJsonImage, _installed_json_image, _source_resource_path
from .hia_machine_transport import _private_zeroed_buffer

MAGIC = int.from_bytes(b'HIAPLN02', 'little')
EMIT_MAGIC = int.from_bytes(b'HIAPLT02', 'little')
SOURCE = _source_resource_path('examples/hia_bootstrap/machine_plan.hiaasm')
SCHEMA = 'hepta.hia.machine-plan-native.v1'
SELECTOR = 'HEPTA_HIA_MACHINE_PLAN_MANIFEST'
_NONCES = itertools.count(1)
_UNCONFIRMED_RETIREMENTS = {}
_EMPTY = object()
_PUBLIC = ('validate_plan', 'register_assignment_witness', 'code_options', 'preservation_checks')
_HELPERS = {'_require': 5, '_permutation': 6, '_terminal_arguments': 7}
_BINARY = (None, operator.add, operator.sub, operator.mul, operator.floordiv,
           operator.truediv, operator.mod, operator.pow, operator.lshift,
           operator.rshift, operator.or_, operator.xor, operator.and_)
_INPLACE = (None, operator.iadd, operator.isub, operator.imul, operator.ifloordiv,
            operator.itruediv, operator.imod, operator.ipow, operator.ilshift,
            operator.irshift, operator.ior, operator.ixor, operator.iand)
_UNARY = (None, operator.pos, operator.neg, operator.invert, operator.not_)
_COMPARE = (None, operator.eq, operator.ne, operator.lt, operator.le, operator.gt,
            operator.ge, lambda a, b: a in b, lambda a, b: a not in b,
            operator.is_, operator.is_not)


class _Cell:
    __slots__ = ('value',)

    def __init__(self, value=_EMPTY):
        self.value = value


@dataclass(frozen=True)
class Issued:
    raw: bytes


def _read_word(data, at):
    return struct.unpack_from('<Q', data, at)[0]


def _capture(frame):
    """Return outside the handler before HIA permits operand retirement."""
    try:
        return True, frame._effect()
    except BaseException as error:
        return False, error


def _capture_with_handler(frame):
    if frame.handled is None:
        return _capture(frame)
    try:
        frame.image._delivery.deliver(frame.handled)
    except BaseException:
        return _capture(frame)


class PlanFrame:
    def __init__(self, image, mode, arguments, captures=(), *, witness=None):
        self.closed = False
        self.state = self.output = None
        self.pending = self.frame_bytes = None
        self.executed = self.completed = False
        self.error = self.handled = None
        self.reply = None
        self.values = []
        self.cells = set()
        self.mode = mode
        self.image = image
        self.witness = witness
        self._terminal_taken = False
        self._yield_taken = False
        self._started = False
        self._retiring = self._retired = self._uncertain = False
        self.nonce = next(_NONCES)
        if self.nonce >= 1 << 64:
            raise OverflowError('native machine-plan continuation nonce exhausted')
        try:
            entry, slots, info, metadata = image.function(mode)
            self.parameter_count = info & 65535
            self.generator = bool((info >> 16) & 1)
            capture_count = info >> 32
            if len(arguments) != self.parameter_count or len(captures) != capture_count:
                raise TypeError('native machine-plan private argument arity differs')
            self.values = [_EMPTY] * slots
            for index in range(slots):
                if image.table[metadata + index] & 2:
                    self.cells.add(index)
                    self.values[index] = _Cell()
            for index, value in enumerate(arguments):
                self._set(index, value)
            for index, cell in enumerate(captures):
                destination = struct.unpack_from('<H', image.table, metadata + slots + 2 * index)[0]
                if type(cell) is not _Cell or destination >= slots:
                    raise RuntimeError('native machine-plan closure representation differs')
                self.cells.add(destination)
                self.values[destination] = cell
            self.state = _private_zeroed_buffer(image.workspace_bytes)
            self.output = _private_zeroed_buffer(2048)
        except BaseException:
            self.close(release=False)
            raise

    def _get(self, slot):
        if type(slot) is not int or not 0 <= slot < len(self.values):
            raise RuntimeError('native machine-plan object slot is outside the frame')
        value = self.values[slot]
        if slot in self.cells:
            value = value.value
        if value is _EMPTY:
            raise RuntimeError('native machine-plan read an unbound object slot')
        return value

    def _set(self, slot, value):
        if type(slot) is not int or not 0 <= slot < len(self.values):
            raise RuntimeError('native machine-plan destination is outside the frame')
        if slot in self.cells:
            self.values[slot].value = value
        else:
            self.values[slot] = value

    def _clear(self, slot):
        self._set(slot, _EMPTY)

    def close(self, *, release=True):
        self.closed = True
        self.pending = self.frame_bytes = self.reply = None
        # The delivered exception already owns the original traceback. Keeping
        # it on its own frame would create an additional frame/error cycle.
        self.error = self.handled = None
        if release:
            self._retire()

    def _retire(self):
        """Retire stack temporaries, then locals, in the HIA-issued order.

        An error traceback owns its original locals until the frame itself
        dies. Generator cancellation also reaches this boundary after Python
        has restored the outer handled-exception context.
        """
        if self._retired:
            return
        if self._uncertain:
            _UNCONFIRMED_RETIREMENTS[self.nonce] = self
            return
        self.closed = True
        if self._started and self.state is not None:
            self._retiring = True
            try:
                self._accept_result(self._invoke(4))
                while self._status == 1:
                    self.service(self.pending)
                    self.step()
                if self._status != 5:
                    raise RuntimeError('native machine-plan frame retirement did not finish')
            except BaseException:
                self._uncertain = True
                _UNCONFIRMED_RETIREMENTS[self.nonce] = self
                raise
            finally:
                self._retiring = False
        else:
            # A partial constructor has not executed a policy instruction.
            # Its argument slots have only the fixed forward frame ownership.
            for index in range(len(self.values)):
                self.values[index] = _EMPTY
        self.values.clear()
        self.cells.clear()
        self.pending = self.frame_bytes = self.reply = None
        self.state = self.output = None
        self._retired = True

    def __del__(self):
        if hasattr(self, '_retired') and not self._retired:
            try:
                self._retire()
            except BaseException:
                # A lost cleanup acknowledgement is retained as unknown. It
                # cannot grant a replay or silently release unconfirmed data.
                _UNCONFIRMED_RETIREMENTS[self.nonce] = self

    def _invoke(self, command, flag=0, error=0, op=0):
        if self.closed and not self._retiring:
            raise RuntimeError('native machine-plan frame is closed')
        sequence = 0 if not self._started else _read_word(self.state, 144)
        value = self.mode if command == 0 else op if command == 2 else flag
        struct.pack_into('<5Q', self.state, 0, command, self.nonce, sequence, value, error)
        self.image.entries += 1
        return self.image._entry(self.image._table_buffer, len(self.image.table),
                                 self.output, len(self.output), self.state, len(self.state))

    def step(self):
        if self.closed and not self._retiring:
            raise RuntimeError('native machine-plan frame is closed')
        if self.pending is not None and not self.completed:
            raise RuntimeError('native machine-plan observation lacks its actual acknowledgement')
        try:
            if not self._started:
                result = self._invoke(0)
                self._started = True
            elif self._status == 2:
                if not self._yield_taken:
                    raise RuntimeError('native machine-plan yielded value was not consumed')
                self._yield_taken = False
                result = self._invoke(3)
            else:
                if self.reply is None or self.pending is None:
                    raise RuntimeError('native machine-plan continuation has no issued result')
                result = self._invoke(1, *self.reply)
            self._accept_result(result)
            return result
        except BaseException:
            self._uncertain = True
            self.close(release=False)
            raise

    def _accept_result(self, result):
        self.pending = self.frame_bytes = self.reply = None
        self.executed = self.completed = False
        self._status = result
        if type(result) is not int or result not in ((1, 5) if self._retiring else (0, 1, 2, 3)):
            raise RuntimeError('native machine-plan continuation returned an invalid status')
        if result == 1:
            head = struct.unpack_from('<10Q', self.output)
            requests = (5, 6) if self._retiring else (1, 2, 3)
            if (head[0] != MAGIC or head[1] != self.nonce or head[2] == 0 or
                    head[2] != _read_word(self.state, 144) or
                    not 1 <= head[4] <= 28 or head[9] not in requests):
                raise RuntimeError('native machine-plan issued a malformed observation')
            size = 128 + 8 * sum(head[5:9])
            if size > len(self.output):
                raise RuntimeError('native machine-plan observation extent differs')
            self.frame_bytes = bytes(self.output[:size])
            self.pending = Issued(self.frame_bytes)
            self.image.observations[head[4]] += 1
        else:
            head = struct.unpack_from('<4Q', self.output)
            if head[:3] != (MAGIC, self.nonce, _read_word(self.state, 144)):
                raise RuntimeError('native machine-plan terminal identity differs')
            if result in (0, 2) and head[3] >= len(self.values):
                raise RuntimeError('native machine-plan terminal value is outside the frame')
            if result in (3, 5) and head[3] != 0:
                raise RuntimeError('native machine-plan terminal has a noncanonical payload')
            self.frame_bytes = bytes(self.output[:32])

    def service(self, issued):
        if (self.closed and not self._retiring) or issued is not self.pending or type(issued) is not Issued:
            raise RuntimeError('native machine-plan observation is not the issued permission')
        if type(issued.raw) is not bytes or issued.raw != self.frame_bytes or self.executed:
            raise RuntimeError('native machine-plan observation changed or was already consumed')
        self.executed = True
        try:
            if self._invoke(2, op=_read_word(issued.raw, 32)) != 4:
                raise RuntimeError('native machine-plan observation claim refused')
            observed = _capture_with_handler(self)
            if observed[0]:
                self.reply = (observed[1], 0)
            else:
                self.error = observed[1]
                self.reply = (0, 1)
            observed = None
            self.completed = True
        except BaseException:
            self._uncertain = True
            self.close(release=False)
            raise

    def _parts(self):
        head = struct.unpack_from('<10Q', self.frame_bytes)
        nd, na, nr, nv = head[5:9]
        values = struct.unpack_from('<' + 'Q' * (nd + na + nr + nv), self.frame_bytes, 128)
        return (head[4], values[:nd], values[nd:nd + na],
                values[nd + na:nd + na + nr], values[nd + na + nr:])

    def _global(self, name):
        from . import hia_machine_plan as module
        if name in _HELPERS:
            return partial(self.image.run, _HELPERS[name])
        if name == 'register_assignment_witness':
            if self.witness is not None:
                return self.witness
            current = module.register_assignment_witness
            if current is module._NATIVE_PUBLIC_WITNESS:
                return self.image.witness
            return current
        if name in vars(module):
            return vars(module)[name]
        return vars(builtins)[name]

    def _call(self, args, raw):
        count, keywords = raw[:2]
        if keywords == 0:
            if count == 0:
                return self._get(args[0])()
            if count == 1:
                return self._get(args[0])(self._get(args[1]))
            if count == 2:
                return self._get(args[0])(self._get(args[1]), self._get(args[2]))
            if count == 3:
                return self._get(args[0])(self._get(args[1]), self._get(args[2]), self._get(args[3]))
            if count == 4:
                return self._get(args[0])(self._get(args[1]), self._get(args[2]), self._get(args[3]), self._get(args[4]))
        # Only keyword-bearing original call sites reach this mechanical form.
        # No borrowed foreign values are saved in this frame's Python locals.
        return self._get(args[0])(
            *(self._get(args[index + 1]) for index in range(count)),
            **{self.image.literal(raw[2 + index]): self._get(args[1 + count + index])
               for index in range(keywords)})

    def _function(self, args, raw, vector):
        mode, generator = raw
        captures = tuple(self.values[slot] for slot in vector)
        if any(type(cell) is not _Cell for cell in captures):
            raise RuntimeError('native machine-plan captured a non-cell')
        if generator:
            frame = PlanFrame(self.image, mode, (self._get(args[0]),), captures,
                              witness=self.witness)
            def native_generator():
                value = None
                try:
                    while True:
                        value = None
                        status = frame.drive()
                        if status == 0:
                            return
                        value = frame.take(yielded=True)
                        yield value
                finally:
                    value = None
                    # The generator frame drops its owner after restoring the
                    # outer exception context. HIA then retires its remaining
                    # stack values and original locals through PlanFrame.
            return native_generator()
        image, witness = self.image, self.witness
        def native_function(*arguments):
            return image.run(mode, *arguments, _captures=captures,
                             _witness=witness)
        return native_function

    def _effect(self):
        op, destinations, args, raw, vector = self._parts()
        flag = 0
        result = _EMPTY
        if op == 1:
            result = self.image.literal(raw[0])
        elif op == 2:
            result = self._global(self.image.literal(raw[0]))
        elif op == 3:
            result = getattr(self._get(args[0]), self.image.literal(raw[0]))
        elif op == 4:
            result = self._get(args[0])[self._get(args[1])]
        elif op == 5:
            if raw[0] >= 128:
                result = _INPLACE[raw[0] - 128](self._get(args[0]), self._get(args[1]))
            else:
                result = _BINARY[raw[0]](self._get(args[0]), self._get(args[1]))
        elif op == 6:
            result = _COMPARE[raw[0]](self._get(args[0]), self._get(args[1]))
        elif op == 7:
            result = _UNARY[raw[0]](self._get(args[0]))
        elif op == 8:
            flag = int(bool(self._get(args[0])))
        elif op == 9:
            result = self._call(args, raw)
        elif op == 10:
            if raw[0] == 1:
                result = [self._get(slot) for slot in vector]
            elif raw[0] == 2:
                result = tuple(self._get(slot) for slot in vector)
            elif raw[0] == 3:
                result = {self._get(slot) for slot in vector}
            elif raw[0] == 4:
                result = dict(zip([self._get(slot) for slot in vector[::2]],
                                  [self._get(slot) for slot in vector[1::2]]))
            else:
                raise RuntimeError('native machine-plan pack kind differs')
        elif op == 11:
            result = iter(self._get(args[0]))
        elif op == 12:
            try:
                result = next(self._get(args[0]))
                flag = 1
            except StopIteration:
                result = None
                flag = 0
        elif op == 13:
            if raw[0] == 1:
                left, = self._get(args[0])
                result = (left,)
                left = None
            elif raw[0] == 2:
                left, right = self._get(args[0])
                result = (left, right)
                left = right = None
            elif raw[0] == 3:
                left, middle, right = self._get(args[0])
                result = (left, middle, right)
                left = middle = right = None
            else:
                raise RuntimeError('native machine-plan unpack arity differs')
        elif op == 14:
            self._get(args[0])[self._get(args[1])] = self._get(args[2])
        elif op == 15:
            result = self._get(args[0])
        elif op == 16:
            for slot in vector:
                self._clear(slot)
        elif op == 17:
            result = slice(self._get(args[0]), self._get(args[1]), self._get(args[2]))
        elif op == 18:
            result = self._function(args, raw, vector)
        elif op == 19:
            from . import hia_program
            result = getattr(hia_program, self.image.literal(raw[0]))
        elif op == 20:
            if raw[0]:
                raise self._get(args[0]) from self._get(args[1])
            raise self._get(args[0])
        elif op == 21:
            flag = int(isinstance(self.error, self._get(args[0])))
        elif op == 22:
            result = self.error
        elif op == 23:
            self._get(args[0]).append(self._get(args[1]))
        elif op == 24:
            self._get(args[0]).extend(self._get(args[1]))
        elif op == 25:
            self._get(args[0]).add(self._get(args[1]))
        elif op == 26:
            self.handled = self.error
        elif op == 27:
            self.handled = None
        elif op == 28:
            for slot in vector:
                # Frame retirement drops a cell reference; it must not clear
                # the cell owned by a separately retained native generator.
                self.values[slot] = _EMPTY
        else:
            raise RuntimeError('unknown native machine-plan object primitive')
        if op == 13:
            for index, destination in enumerate(destinations):
                self._set(destination, result[index])
        elif destinations:
            if len(destinations) != 1 or result is _EMPTY:
                raise RuntimeError('native machine-plan primitive result arity differs')
            self._set(destinations[0], result)
        result = None
        return flag

    def drive(self):
        status = self.step()
        while status == 1:
            self.service(self.pending)
            status = self.step()
        if status == 3:
            if self.error is None:
                raise RuntimeError('native machine-plan failed without an actual exception')
            self._terminal_taken = True
            error, self.error = self.error, None
            self.handled = None
            try:
                self.image._delivery.deliver(error)
                raise RuntimeError('native machine-plan exception delivery returned')
            finally:
                error = None
        return status

    def take(self, *, yielded=False):
        if self.closed or self._status != (2 if yielded else 0):
            raise RuntimeError('native machine-plan value is not at the selected terminal')
        if self._yield_taken if yielded else self._terminal_taken:
            raise RuntimeError('native machine-plan value permission was already consumed')
        if yielded:
            self._yield_taken = True
        else:
            self._terminal_taken = True
        return self._get(_read_word(self.frame_bytes, 24))


class NativeMachinePlanControl(NativeHiaJsonImage):
    def __init__(self, image, expected_sha256):
        super().__init__(image, expected_sha256)
        self._initialize_control()

    def _initialize_control(self):
        self.entries = 0
        self.observations = Counter()
        self._delivery = ExceptionDelivery.from_hia(self)
        source = ctypes.create_string_buffer(struct.pack('<8Q', EMIT_MAGIC, *([0] * 7)))
        output = _private_zeroed_buffer(1 << 20)
        workspace = _private_zeroed_buffer(96)
        size = self._entry(source, 64, output, len(output), workspace, len(workspace))
        if type(size) is not int or not 64 <= size <= len(output):
            raise RuntimeError('native machine-plan policy emission refused')
        self.table = bytes(output[:size])
        if struct.unpack_from('<2Q', self.table) != (MAGIC, len(self.table)):
            raise RuntimeError('native machine-plan policy table identity differs')
        functions, instructions, base, offsets, literals, count = struct.unpack_from('<6Q', self.table, 16)
        if (functions < 7 or base != 64 or base + functions * 32 > len(self.table)
                or offsets + instructions * 4 > len(self.table)
                or literals + count * 4 > len(self.table)):
            raise RuntimeError('native machine-plan policy table extents differ')
        self.function_count = functions
        self._literal_offsets, self._literal_count = literals, count
        self._literals = {}
        self.workspace_bytes = 1024 + 8 * max(self.function(mode)[1]
                                             for mode in range(1, functions + 1))
        self._table_buffer = ctypes.create_string_buffer(self.table, len(self.table))

    def function(self, mode):
        if type(mode) is not int or not 1 <= mode <= self.function_count:
            raise RuntimeError('native machine-plan entry identity differs')
        entry, slots, info, metadata = struct.unpack_from('<4Q', self.table, 64 + (mode - 1) * 32)
        if metadata + slots + 2 * (info >> 32) > len(self.table):
            raise RuntimeError('native machine-plan closure extent differs')
        return entry, slots, info, metadata

    def literal(self, index):
        if type(index) is not int or not 0 <= index < self._literal_count:
            raise RuntimeError('native machine-plan literal identity differs')
        if index not in self._literals:
            at = struct.unpack_from('<I', self.table, self._literal_offsets + index * 4)[0]
            kind, size = struct.unpack_from('<BQ', self.table, at)
            if at + 9 + size > len(self.table):
                raise RuntimeError('native machine-plan literal extent differs')
            raw = self.table[at + 9:at + 9 + size]
            if kind == 0 and size == 0:
                value = None
            elif kind == 1 and raw in (b'\0', b'\1'):
                value = raw == b'\1'
            elif kind == 2:
                value = int(raw)
            elif kind == 3:
                value = raw.decode('utf-8')
            else:
                raise RuntimeError('native machine-plan literal kind differs')
            self._literals[index] = value
        return self._literals[index]

    def run(self, mode, *arguments, _captures=(), _witness=None):
        frame = PlanFrame(self, mode, arguments, _captures, witness=_witness)
        try:
            if frame.drive() != 0:
                raise RuntimeError('native machine-plan public entry yielded')
            return frame.take()
        finally:
            frame.close(release=sys.exc_info()[0] is None)

    def validate(self, checked, plan, witness=None):
        return self.run(1, checked, plan, _witness=witness)

    def witness(self, checked, assignments, *, allow_leaf_registers=False):
        return self.run(2, checked, assignments, allow_leaf_registers)

    def code_options(self, plan):
        return self.run(3, plan)

    def preservation_checks(self, plan, checked=None, *, witness=None):
        return self.run(4, plan, checked, _witness=witness)


def installed_machine_plan(manifest_path):
    return _installed_json_image(manifest_path, SOURCE, SCHEMA, NativeMachinePlanControl)

"""Finite source compiler for the four machine-plan APIs and their helpers.

This is an authoring tool.  Its output is ordinary HIA control flow.  Runtime
never imports this module or executes a retained Python policy function.
Object operations remain individually visible foreign requests; their result
does not choose the next operation until the HIA continuation acknowledges it.
"""
from __future__ import annotations

import ast
from dataclasses import dataclass


OPS = {name: i + 1 for i, name in enumerate((
    'CONST', 'GLOBAL', 'ATTR', 'ITEM', 'BINARY', 'COMPARE', 'UNARY', 'TRUTH',
    'CALL', 'PACK', 'ITER', 'NEXT', 'UNPACK', 'SET_ITEM', 'STORE', 'RELEASE',
    'SLICE', 'FUNCTION', 'IMPORT', 'RAISE', 'EXCEPTION_MATCH', 'ERROR',
    'APPEND', 'EXTEND', 'SET_ADD', 'HANDLED', 'CLEAR_HANDLED', 'DROP_SLOT'))}
BINARY = {name: i + 1 for i, name in enumerate((
    'Add', 'Sub', 'Mult', 'FloorDiv', 'Div', 'Mod', 'Pow', 'LShift',
    'RShift', 'BitOr', 'BitXor', 'BitAnd'))}
COMPARE = {name: i + 1 for i, name in enumerate((
    'Eq', 'NotEq', 'Lt', 'LtE', 'Gt', 'GtE', 'In', 'NotIn', 'Is', 'IsNot'))}
UNARY = {'UAdd': 1, 'USub': 2, 'Invert': 3, 'Not': 4}
PACK = {'List': 1, 'Tuple': 2, 'Set': 3, 'Dict': 4}
PUBLIC = ('validate_plan', 'register_assignment_witness', 'code_options',
          'preservation_checks')
HELPERS = ('_require', '_permutation', '_terminal_arguments')


@dataclass(frozen=True)
class Ref:
    slot: int
    temporary: bool = True


class Compiler:
    def __init__(self, source):
        self.source = source
        self.tree = ast.parse(source)
        self.literals = []
        self.literal_indices = {}
        self.functions = []
        self.by_name = {}
        for name in (*PUBLIC, *HELPERS):
            node = next(n for n in self.tree.body
                        if isinstance(n, ast.FunctionDef) and n.name in
                        (name, '_reference_' + name))
            function = Function(self, name, node)
            self.functions.append(function)
            self.by_name[name] = function
        index = 0
        while index < len(self.functions):
            self.functions[index].compile()
            index += 1
        for mode, function in enumerate(self.functions, 1):
            function.mode = mode
        for function in self.functions:
            function.resolve()

    def literal(self, value):
        if type(value) not in (type(None), bool, int, str, tuple, frozenset):
            raise ValueError('unreviewed machine-plan literal ' + repr(value))
        key = (type(value), value)
        if key not in self.literal_indices:
            self.literal_indices[key] = len(self.literals)
            self.literals.append(value)
        return self.literal_indices[key]

    def nested(self, parent, node, kind):
        name = parent.name + ':' + kind + ':' + str(len(self.functions))
        function = Function(self, name, node, parent=parent, kind=kind)
        self.functions.append(function)
        return function


class Function:
    def __init__(self, compiler, name, node, *, parent=None, kind='function'):
        self.compiler, self.name, self.node = compiler, name, node
        self.parent, self.kind = parent, kind
        self.instructions, self.locals, self.captures = [], {}, {}
        self.scopes = []
        self.temporary_slots = set()
        self.cell_slots = set()
        self.next_slot = 0
        self.next_label = 0
        self.handlers = []
        self.loop_stack = []
        if kind == 'generator':
            self.parameters = ['.0']
        else:
            args = node.args
            if args.posonlyargs or args.vararg or args.kwarg:
                raise ValueError('unsupported finite policy signature')
            self.parameters = [a.arg for a in args.args + args.kwonlyargs]
        for name in self.parameters:
            self.local(name)
        if kind == 'function':
            # Comprehension bindings have separate inline scopes.  They must
            # neither overwrite nor retain an unrelated outer local.
            def stores(value):
                if isinstance(value, (ast.ListComp, ast.SetComp, ast.DictComp,
                                      ast.GeneratorExp, ast.Lambda)):
                    return
                if isinstance(value, ast.Name) and isinstance(value.ctx, ast.Store):
                    self.local(value.id)
                if isinstance(value, ast.ImportFrom):
                    for alias in value.names:
                        self.local(alias.asname or alias.name)
                if isinstance(value, ast.ExceptHandler) and value.name:
                    # CPython deletes the except binding even when its body
                    # raises. It is not a traceback-retained function local.
                    if value.name not in self.locals:
                        self.locals[value.name] = self.slot()
                for child in ast.iter_child_nodes(value):
                    stores(child)
            for statement in node.body:
                stores(statement)

    def slot(self, temporary=True):
        value = Ref(self.next_slot, temporary)
        self.next_slot += 1
        if temporary:
            self.temporary_slots.add(value.slot)
        return value

    def local(self, name):
        if name not in self.locals:
            self.locals[name] = self.slot(False)
        return self.locals[name]

    def variable(self, name):
        for scope in reversed(self.scopes):
            if name in scope:
                return scope[name]
        if name in self.locals:
            return self.locals[name]
        if name in self.captures:
            return self.captures[name][0]
        if self.parent is not None:
            outer = self.parent.variable(name)
            if outer is not None:
                self.parent.cell_slots.add(outer.slot)
                own = self.slot(False)
                self.captures[name] = (own, outer)
                return own
        return None

    def label(self):
        value = 'L' + str(self.next_label)
        self.next_label += 1
        return value

    def mark(self, label):
        self.instructions.append({'kind': 'label', 'label': label})

    def emit(self, kind, **fields):
        self.instructions.append({'kind': kind, **fields})

    def jump(self, label):
        self.emit('jump', target=label)

    def effect(self, operation, arguments=(), *, raw=(), vector=(), count=1,
               consume=(), destination=None):
        destinations = ([destination] if destination is not None else
                        [self.slot() for _ in range(count)])
        retired = []
        for ref in consume:
            if ref is not None and ref.temporary and ref not in retired:
                retired.append(ref)
        self.emit('effect', opcode=OPS[operation], arguments=list(arguments),
                  raw=list(raw), vector=list(vector), destinations=destinations,
                  consume=retired,
                  handler=self.handlers[-1] if self.handlers else None)
        return destinations[0] if len(destinations) == 1 else tuple(destinations)

    def release(self, refs):
        values = []
        seen = set()
        for ref in refs:
            if ref is not None and ref.temporary and ref.slot not in seen:
                seen.add(ref.slot)
                values.append(ref)
        if values:
            self.emit('effect', opcode=OPS['RELEASE'], arguments=[], raw=[],
                      vector=values, destinations=[], consume=[], handler=None)

    def constant(self, value):
        return self.effect('CONST', raw=(self.compiler.literal(value),))

    def copy(self, value):
        return self.effect('STORE', (value,))

    def store(self, destination, value, *, consume=True):
        self.effect('STORE', (value,), destination=destination,
                    consume=(value,) if consume else ())

    def truth(self, value, yes, no):
        self.effect('TRUTH', (value,), count=0, consume=(value,))
        self.emit('flag', yes=yes, no=no)

    def condition(self, node, yes, no):
        if isinstance(node, ast.BoolOp):
            for child in node.values[:-1]:
                onward = self.label()
                self.condition(child, onward if isinstance(node.op, ast.And) else yes,
                               no if isinstance(node.op, ast.And) else onward)
                self.mark(onward)
            self.condition(node.values[-1], yes, no)
        elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            self.condition(node.operand, no, yes)
        else:
            self.truth(self.expression(node), yes, no)

    def expression(self, node):
        if isinstance(node, ast.Constant):
            return self.constant(node.value)
        if isinstance(node, ast.Name):
            value = self.variable(node.id)
            return self.copy(value) if value is not None else self.effect(
                'GLOBAL', raw=(self.compiler.literal(node.id),))
        if isinstance(node, ast.Attribute):
            owner = self.expression(node.value)
            return self.effect('ATTR', (owner,), raw=(self.compiler.literal(node.attr),),
                               consume=(owner,))
        if isinstance(node, ast.Subscript):
            owner, key = self.expression(node.value), self.expression(node.slice)
            return self.effect('ITEM', (owner, key), consume=(owner, key))
        if isinstance(node, ast.Slice):
            values = [self.expression(v) if v is not None else self.constant(None)
                      for v in (node.lower, node.upper, node.step)]
            return self.effect('SLICE', values, consume=values)
        if isinstance(node, ast.BinOp):
            left, right = self.expression(node.left), self.expression(node.right)
            return self.effect('BINARY', (left, right), raw=(BINARY[type(node.op).__name__],),
                               consume=(left, right))
        if isinstance(node, ast.UnaryOp):
            value = self.expression(node.operand)
            return self.effect('UNARY', (value,), raw=(UNARY[type(node.op).__name__],),
                               consume=(value,))
        if isinstance(node, ast.Compare):
            if len(node.ops) != 1:
                raise ValueError('unreviewed chained comparison')
            left, right = self.expression(node.left), self.expression(node.comparators[0])
            return self.effect('COMPARE', (left, right), raw=(COMPARE[type(node.ops[0]).__name__],),
                               consume=(left, right))
        if isinstance(node, ast.BoolOp):
            result, done = self.slot(), self.label()
            for index, child in enumerate(node.values):
                value = self.expression(child)
                self.store(result, value)
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(self.copy(result), onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
            self.mark(done)
            return result
        if isinstance(node, ast.IfExp):
            result, yes, no, done = self.slot(), self.label(), self.label(), self.label()
            self.condition(node.test, yes, no)
            self.mark(yes); self.store(result, self.expression(node.body)); self.jump(done)
            self.mark(no); self.store(result, self.expression(node.orelse)); self.mark(done)
            return result
        if isinstance(node, (ast.List, ast.Tuple, ast.Set, ast.Dict)):
            kind = PACK[type(node).__name__]
            if isinstance(node, ast.Dict):
                if any(key is None for key in node.keys):
                    raise ValueError('unreviewed dictionary expansion')
                children = [value for pair in zip(node.keys, node.values) for value in pair]
            else:
                children = node.elts
            if any(isinstance(child, ast.Starred) for child in children):
                if kind != PACK['List']:
                    raise ValueError('unreviewed starred pack')
                result = self.effect('PACK', raw=(kind,), vector=())
                for child in children:
                    value = self.expression(child.value if isinstance(child, ast.Starred) else child)
                    self.effect('EXTEND' if isinstance(child, ast.Starred) else 'APPEND',
                                (result, value), count=0, consume=(value,))
                return result
            values = [self.expression(child) for child in children]
            return self.effect('PACK', raw=(kind,), vector=values, consume=reversed(values))
        if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp)):
            return self.comprehension(node)
        if isinstance(node, ast.GeneratorExp):
            iterator_value = self.expression(node.generators[0].iter)
            iterator = self.effect('ITER', (iterator_value,), consume=(iterator_value,))
            nested = self.compiler.nested(self, node, 'generator')
            # Compile now so closure cells are fixed before the request which
            # creates this generator.  Later outer assignments update cells.
            nested.compile()
            return self.effect('FUNCTION', (iterator,), raw=(nested, 1),
                               vector=[pair[1] for pair in nested.captures.values()],
                               consume=(iterator,))
        if isinstance(node, ast.Lambda):
            nested = self.compiler.nested(self, node, 'lambda')
            nested.compile()
            return self.effect('FUNCTION', raw=(nested, 0),
                               vector=[pair[1] for pair in nested.captures.values()])
        if isinstance(node, ast.Call):
            if any(isinstance(arg, ast.Starred) for arg in node.args) or len(node.args) > 4:
                raise ValueError('unreviewed call extent')
            if any(keyword.arg is None for keyword in node.keywords) or len(node.keywords) > 2:
                raise ValueError('unreviewed call keywords')
            callee = self.expression(node.func)
            args = [self.expression(arg) for arg in node.args]
            keys = [self.compiler.literal(keyword.arg) for keyword in node.keywords]
            values = [self.expression(keyword.value) for keyword in node.keywords]
            return self.effect('CALL', [callee, *args, *values],
                               raw=(len(args), len(keys), *keys),
                               consume=(callee, *args, *values))
        if isinstance(node, ast.JoinedStr):
            values = []
            for child in node.values:
                if isinstance(child, ast.Constant):
                    values.append(self.constant(child.value))
                elif isinstance(child, ast.FormattedValue):
                    if child.conversion != -1 or child.format_spec is not None:
                        raise ValueError('unreviewed f-string format')
                    callee = self.effect('GLOBAL', raw=(self.compiler.literal('format'),))
                    value = self.expression(child.value)
                    values.append(self.effect('CALL', (callee, value), raw=(1, 0),
                                              consume=(callee, value)))
                else:
                    raise ValueError('unreviewed f-string')
            result = self.constant('')
            for value in values:
                result = self.effect('BINARY', (result, value), raw=(BINARY['Add'],),
                                     consume=(result, value))
            return result
        raise ValueError('unreviewed expression: ' + ast.dump(node))

    def assign(self, target, value):
        if isinstance(target, ast.Name):
            destination = self.variable(target.id)
            if destination is None:
                destination = self.local(target.id)
            self.store(destination, value)
        elif isinstance(target, ast.Subscript):
            owner, key = self.expression(target.value), self.expression(target.slice)
            self.effect('SET_ITEM', (owner, key, value), count=0,
                        consume=(value, owner, key))
        elif isinstance(target, (ast.Tuple, ast.List)):
            pieces = self.effect('UNPACK', (value,), raw=(len(target.elts),),
                                 count=len(target.elts), consume=(value,))
            if len(target.elts) == 1:
                pieces = (pieces,)
            for child, piece in zip(target.elts, pieces):
                self.assign(child, piece)
        else:
            raise ValueError('unreviewed assignment: ' + ast.dump(target))

    def iterate(self, generators, body, *, first=None):
        if not generators:
            body(); return
        generator = generators[0]
        if generator.is_async:
            raise ValueError('asynchronous policy is not admitted')
        if first is None:
            iterable = self.expression(generator.iter)
            iterator = self.effect('ITER', (iterable,), consume=(iterable,))
        else:
            iterator = first
        head, found, done = self.label(), self.label(), self.label()
        self.mark(head)
        value = self.effect('NEXT', (iterator,))
        self.emit('flag', yes=found, no=done)
        self.mark(found); self.assign(generator.target, value)
        for condition in generator.ifs:
            onward = self.label()
            self.condition(condition, onward, head)
            self.mark(onward)
        self.iterate(generators[1:], body)
        self.jump(head); self.mark(done)
        self.release((value, iterator))

    def comp_scope(self, generators, *, generator=False):
        names = {n.id for generator in generators for n in ast.walk(generator.target)
                 if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store)}
        return {name: self.slot(not generator) for name in sorted(names)}

    def comprehension(self, node):
        iterable = self.expression(node.generators[0].iter)
        first = self.effect('ITER', (iterable,), consume=(iterable,))
        kind = ('Dict' if isinstance(node, ast.DictComp) else
                'Set' if isinstance(node, ast.SetComp) else 'List')
        result = self.effect('PACK', raw=(PACK[kind],), vector=())
        scope = self.comp_scope(node.generators)
        self.scopes.append(scope)
        def body():
            if kind == 'Dict':
                key, value = self.expression(node.key), self.expression(node.value)
                self.effect('SET_ITEM', (result, key, value), count=0,
                            consume=(value, key))
            else:
                value = self.expression(node.elt)
                self.effect('SET_ADD' if kind == 'Set' else 'APPEND',
                            (result, value), count=0, consume=(value,))
        self.iterate(node.generators, body, first=first)
        self.scopes.pop()
        self.release(reversed(tuple(scope.values())))
        return result

    def statements(self, statements):
        for node in statements:
            if isinstance(node, ast.Expr):
                if not isinstance(node.value, ast.Constant):
                    self.release((self.expression(node.value),))
            elif isinstance(node, ast.Assign):
                value = self.expression(node.value)
                if len(node.targets) != 1:
                    raise ValueError('unreviewed chained assignment')
                self.assign(node.targets[0], value)
            elif isinstance(node, ast.AugAssign):
                if not isinstance(node.target, ast.Name):
                    raise ValueError('unreviewed augmented target')
                left = self.expression(ast.Name(id=node.target.id, ctx=ast.Load()))
                right = self.expression(node.value)
                value = self.effect('BINARY', (left, right),
                                    raw=(128 + BINARY[type(node.op).__name__],),
                                    consume=(left, right))
                self.assign(node.target, value)
            elif isinstance(node, ast.If):
                yes, no, done = self.label(), self.label(), self.label()
                self.condition(node.test, yes, no)
                self.mark(yes); self.statements(node.body); self.jump(done)
                self.mark(no); self.statements(node.orelse); self.mark(done)
            elif isinstance(node, ast.For):
                iterable = self.expression(node.iter)
                iterator = self.effect('ITER', (iterable,), consume=(iterable,))
                head, found, done = self.label(), self.label(), self.label()
                self.mark(head)
                value = self.effect('NEXT', (iterator,))
                self.emit('flag', yes=found, no=done)
                self.mark(found); self.assign(node.target, value)
                self.loop_stack.append((head, done))
                self.statements(node.body)
                self.loop_stack.pop()
                self.jump(head); self.mark(done)
                self.release((value, iterator)); self.statements(node.orelse)
            elif isinstance(node, ast.Return):
                value = self.expression(node.value) if node.value else self.constant(None)
                self.emit('return', value=value)
            elif isinstance(node, ast.ImportFrom):
                if node.level != 1 or node.module != 'hia_program':
                    raise ValueError('unreviewed import')
                for alias in node.names:
                    value = self.effect('IMPORT', raw=(self.compiler.literal(alias.name),))
                    self.assign(ast.Name(id=alias.asname or alias.name, ctx=ast.Store()), value)
            elif isinstance(node, ast.Raise):
                if node.exc is None:
                    raise ValueError('bare re-raise is not used by this policy')
                value = self.expression(node.exc)
                cause = self.expression(node.cause) if node.cause else self.constant(None)
                self.effect('RAISE', (value, cause), raw=(int(node.cause is not None),), count=0)
            elif isinstance(node, ast.Try):
                if len(node.handlers) != 1 or node.orelse or node.finalbody:
                    raise ValueError('unreviewed exception control')
                handler = node.handlers[0]
                if handler.type is None:
                    raise ValueError('unreviewed bare handler')
                caught, matched, not_matched, done = (self.label() for _ in range(4))
                self.handlers.append(caught)
                self.statements(node.body)
                self.handlers.pop(); self.jump(done); self.mark(caught)
                typ = self.expression(handler.type)
                self.effect('EXCEPTION_MATCH', (typ,), count=0, consume=(typ,))
                self.emit('flag', yes=matched, no=not_matched)
                self.mark(not_matched); self.emit('error_return')
                self.mark(matched)
                if handler.name:
                    error = self.effect('ERROR')
                    self.assign(ast.Name(id=handler.name, ctx=ast.Store()), error)
                self.effect('HANDLED', count=0)
                self.statements(handler.body)
                self.effect('CLEAR_HANDLED', count=0)
                if handler.name:
                    self.store(self.local(handler.name), self.constant(None))
                self.mark(done)
            elif isinstance(node, ast.Pass):
                pass
            else:
                raise ValueError('unreviewed statement: ' + ast.dump(node))

    def compile(self):
        if getattr(self, '_compiled', False):
            return
        self._compiled = True
        if self.kind == 'generator':
            # Unlike inlined comprehension bindings, a generator's targets
            # remain locals in a retained exception traceback.
            scope = self.comp_scope(self.node.generators, generator=True)
            self.scopes.append(scope)
            def body():
                value = self.expression(self.node.elt)
                self.emit('yield', value=value)
                self.release((value,))
            self.iterate(self.node.generators, body,
                         first=self.copy(self.local('.0')))
            self.scopes.pop(); self.release(reversed(tuple(scope.values())))
        elif self.kind == 'lambda':
            self.emit('return', value=self.expression(self.node.body))
        else:
            self.statements(self.node.body)
        self.emit('return', value=self.constant(None))

    def resolve(self):
        labels, final = {}, []
        for instruction in self.instructions:
            if instruction['kind'] == 'label':
                labels[instruction['label']] = len(final) + 1
            else:
                final.append(dict(instruction, pc=len(final) + 1))
        for instruction in final:
            for key in ('target', 'yes', 'no', 'handler'):
                if key in instruction and instruction[key] is not None:
                    instruction[key] = labels[instruction[key]]
            if instruction['kind'] == 'effect':
                instruction['raw'] = [value.mode if isinstance(value, Function) else value
                                      for value in instruction['raw']]
        self.instructions = final


def compile_policy(source):
    return Compiler(source)

"""Compile the complete machine-plan control program to one HIA image.

The image emits its own immutable instruction/literal table and interprets it
in HIA.  The table is not supplied by a hosted policy planner at runtime.
"""
from __future__ import annotations

import ast
from pathlib import Path
import struct
import sys

ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.hia_exception_delivery import BODY as EXCEPTION_BODY
from tools.hia_machine_plan_control import compile_policy, OPS

MAGIC = int.from_bytes(b'HIAPLN02', 'little')
EMIT_MAGIC = int.from_bytes(b'HIAPLT02', 'little')
ABI = 0xfffffffd
OUTPUT = 2048


def program():
    return compile_policy((ROOT / 'hepta/hia_machine_plan.py').read_text())


def table(policy):
    starts = {}
    count = 0
    for function in policy.functions:
        starts[function.mode] = count + 1
        count += len(function.instructions)
    data = bytearray(64 + len(policy.functions) * 32)
    for function in policy.functions:
        metadata = len(data)
        data += bytes((int(i in function.temporary_slots) |
                       (2 * int(i in function.cell_slots)))
                      for i in range(function.next_slot))
        for own, outer in function.captures.values():
            data += struct.pack('<H', own.slot)
        info = (len(function.parameters) |
                (int(function.kind == 'generator') << 16) |
                (len(function.captures) << 32))
        struct.pack_into('<4Q', data, 64 + (function.mode - 1) * 32,
                         starts[function.mode], function.next_slot, info, metadata)
    offsets_at = len(data)
    data += b'\0' * (4 * count)
    ordinal = 0
    for function in policy.functions:
        shift = starts[function.mode] - 1
        for instruction in function.instructions:
            struct.pack_into('<I', data, offsets_at + ordinal * 4, len(data))
            ordinal += 1
            kind = instruction['kind']
            if kind == 'effect':
                destinations, arguments = instruction['destinations'], instruction['arguments']
                raw, vector = instruction['raw'], instruction['vector']
                consume = instruction['consume']
                handler = instruction['handler']
                data += struct.pack('<6BH I H', 1, instruction['opcode'], len(destinations),
                                    len(arguments), len(raw), len(consume), len(vector),
                                    handler + shift if handler else 0, 0)
                for ref in (*destinations, *arguments):
                    data += struct.pack('<H', ref.slot)
                for value in raw:
                    data += struct.pack('<I', value)
                for ref in (*vector, *consume):
                    data += struct.pack('<H', ref.slot)
            elif kind == 'jump':
                data += struct.pack('<BI', 2, instruction['target'] + shift)
            elif kind == 'flag':
                data += struct.pack('<BII', 3, instruction['yes'] + shift,
                                    instruction['no'] + shift)
            elif kind in ('return', 'yield'):
                data += struct.pack('<BH', 4 if kind == 'return' else 5,
                                    instruction['value'].slot)
            elif kind == 'error_return':
                data += b'\6'
            else:
                raise ValueError('unrendered instruction')
    literals_at = len(data)
    data += b'\0' * (4 * len(policy.literals))
    for index, value in enumerate(policy.literals):
        struct.pack_into('<I', data, literals_at + 4 * index, len(data))
        if value is None:
            kind, raw = 0, b''
        elif type(value) is bool:
            kind, raw = 1, bytes((int(value),))
        elif type(value) is int:
            kind, raw = 2, str(value).encode('ascii')
        elif type(value) is str:
            kind, raw = 3, value.encode('utf-8')
        else:
            raise ValueError('unrendered literal')
        data += struct.pack('<BQ', kind, len(raw)) + raw
    data += bytes((-len(data)) % 8)
    struct.pack_into('<8Q', data, 0, MAGIC, len(data), len(policy.functions), count,
                     64, offsets_at, literals_at, len(policy.literals))
    return bytes(data)


BODY = r'''
def machine_plan(s:readbuf,o:mutbuf,w:mutbuf) -> u32:
    if length(s) == 64:
        if word(s,0) == EMIT_MAGIC:
            return emit_policy(o,w)
        return emit_exception_delivery(s,o,w)
    if length(s) != TABLE_BYTES or word(s,0) != MAGIC or word(s,8) != TABLE_BYTES:
        return ABI
    if length(o) < OUTPUT_BYTES or length(w) != WORKSPACE_BYTES:
        return ABI
    command=get(w,0)
    if command == 0:
        if get(w,128) != 0 or get(w,8) == 0 or get(w,16) != 0:
            return ABI
        mode=get(w,24)
        if mode == 0 or mode > word(s,16):
            return ABI
        info=64+(mode-1)*32
        put(w,128,MAGIC)
        put(w,136,get(w,8))
        put(w,144,0)
        put(w,152,mode)
        put(w,160,word(s,info))
        put(w,168,0)
        put(w,176,0)
        put(w,216,0)
        put(w,248,word(s,info+8))
        put(w,256,word(s,info+24))
        put(w,264,0)
    else:
        if get(w,128) != MAGIC or get(w,8) != get(w,136) or get(w,16) != get(w,144):
            return ABI
        stage=get(w,168)
        if command == 2:
            if stage != 1 or get(w,24) != get(w,184) or get(w,32) != 0:
                return ABI
            put(w,168,2)
            return 4
        if command == 3:
            if stage != 4 or get(w,24) != 0 or get(w,32) != 0:
                return ABI
            put(w,160,get(w,160)+1)
            put(w,168,0)
        else:
            if command == 4:
                if (stage != 4 and stage != 5 and stage != 7) or get(w,24) != 0 or get(w,32) != 0:
                    return ABI
                put(w,304,0)
                put(w,168,8)
            else:
                if command != 1 or stage != 2 or get(w,24) > 1 or get(w,32) > 1:
                    return ABI
                answer=acknowledge(s,w)
                if answer != 0:
                    return answer
    return dispatch(s,o,w)

def acknowledge(s:readbuf,w:mutbuf) -> u64:
    request=get(w,208)
    op=get(w,184)
    if get(w,32) != 0:
        if request != 1:
            return ABI
        put(w,264,1)
        put(w,168,6)
        put(w,272,0)
        return 0
    if request == 3:
        put(w,1024+get(w,280)*8,0)
        put(w,168,6)
        return 0
    if request == 5:
        if get(w,24) != 0:
            return ABI
        put(w,1024+get(w,280)*8,0)
        put(w,168,8)
        return 0
    if request == 6:
        if get(w,24) != 0:
            return ABI
        put(w,304,get(w,304)+1)
        put(w,168,8)
        return 0
    if request == 2:
        clear_refs(s,w,get(w,288),get(w,296))
        if get(w,264) != 0:
            put(w,168,6)
        else:
            put(w,160,get(w,160)+1)
            put(w,168,0)
        return 0
    at=get(w,200)
    if op == TRUTH or op == NEXT or op == EXCEPTION_MATCH:
        put(w,176,get(w,24))
    else:
        if get(w,24) != 0:
            return ABI
    destinations=byte(s,at+2)
    i=0
    while i < destinations:
        slot=short(s,at+14+i*2)
        if slot >= get(w,248):
            return ABI
        if (byte(s,get(w,256)+slot)&1) != 0:
            if get(w,216) == 18446744073709551615:
                return ABI
            put(w,216,get(w,216)+1)
            put(w,1024+slot*8,get(w,216))
        i=i+1
    if op == RELEASE:
        start=at+14+destinations*2+byte(s,at+3)*2+byte(s,at+4)*4
        clear_refs(s,w,start,short(s,at+6))
    consumed=byte(s,at+5)
    if consumed != 0:
        put(w,288,at+14+destinations*2+byte(s,at+3)*2+byte(s,at+4)*4+short(s,at+6)*2)
        put(w,296,consumed)
        put(w,168,3)
    else:
        put(w,160,get(w,160)+1)
        put(w,168,0)
    return 0

def clear_refs(s:readbuf,w:mutbuf,at:u64,count:u64) -> u64:
    i=0
    while i < count:
        slot=short(s,at+i*2)
        put(w,1024+slot*8,0)
        i=i+1
    return 0

def dispatch(s:readbuf,o:mutbuf,w:mutbuf) -> u64:
    while True:
        stage=get(w,168)
        if stage == 8:
            return frame_retire(s,o,w)
        if stage == 3:
            return retire(s,o,w,get(w,288),get(w,296))
        if stage == 6:
            answer=unwind(s,o,w)
            if answer != 5:
                return answer
        if get(w,168) != 0:
            return ABI
        pc=get(w,160)
        if pc == 0 or pc > word(s,24):
            return ABI
        at=small(s,word(s,40)+(pc-1)*4)
        kind=byte(s,at)
        if kind == 1:
            put(w,200,at)
            put(w,192,small(s,at+8))
            return effect(s,o,w,at)
        if kind == 2:
            put(w,160,small(s,at+1))
        else:
            if kind == 3:
                put(w,160,small(s,at+choose(get(w,176)!=0,1,5)))
            else:
                if kind == 4 or kind == 5:
                    put(w,168,choose(kind == 4,5,4))
                    finish(o,w,short(s,at+1))
                    return choose(kind == 4,0,2)
                if kind == 6:
                    put(w,168,7)
                    finish(o,w,0)
                    return 3
                return ABI
    return ABI

def frame_retire(s:readbuf,o:mutbuf,w:mutbuf) -> u64:
    latest=0
    selected=0
    i=0
    while i < get(w,248):
        birth=get(w,1024+i*8)
        if birth > latest:
            latest=birth
            selected=i
        i=i+1
    if latest != 0:
        put(w,280,selected)
        header(o,w,RELEASE,0,0,0,1,5)
        put(o,128,selected)
        return 1
    index=get(w,304)
    if index < get(w,248):
        header(o,w,DROP_SLOT,0,0,0,1,6)
        put(o,128,index)
        return 1
    put(w,168,9)
    finish(o,w,0)
    return 5

def unwind(s:readbuf,o:mutbuf,w:mutbuf) -> u64:
    at=get(w,200)
    if get(w,272) == 0:
        put(w,272,1)
        count=byte(s,at+5)
        if count != 0:
            start=at+14+byte(s,at+2)*2+byte(s,at+3)*2+byte(s,at+4)*4+short(s,at+6)*2
            put(w,288,start)
            put(w,296,count)
            return retire(s,o,w,start,count)
    latest=0
    selected=0
    i=0
    while i < get(w,248):
        birth=get(w,1024+i*8)
        if birth > latest:
            latest=birth
            selected=i
        i=i+1
    if latest != 0:
        put(w,280,selected)
        header(o,w,RELEASE,0,0,0,1,3)
        put(o,128,selected)
        return 1
    handler=get(w,192)
    if handler != 0:
        put(w,160,handler)
        put(w,168,0)
        put(w,264,0)
        return 5
    put(w,168,7)
    finish(o,w,0)
    return 3

def effect(s:readbuf,o:mutbuf,w:mutbuf,at:u64) -> u64:
    op=byte(s,at+1)
    nd=byte(s,at+2)
    na=byte(s,at+3)
    nr=byte(s,at+4)
    nv=short(s,at+6)
    if op == 0 or op > 28 or 128+8*(nd+na+nr+nv) > length(o):
        return ABI
    header(o,w,op,nd,na,nr,nv,1)
    source=at+14
    target=128
    i=0
    while i < nd+na:
        value=short(s,source)
        if value >= get(w,248):
            return ABI
        put(o,target,value)
        source=source+2
        target=target+8
        i=i+1
    i=0
    while i < nr:
        put(o,target,small(s,source))
        source=source+4
        target=target+8
        i=i+1
    i=0
    while i < nv:
        value=short(s,source)
        if value >= get(w,248):
            return ABI
        put(o,target,value)
        source=source+2
        target=target+8
        i=i+1
    return 1

def retire(s:readbuf,o:mutbuf,w:mutbuf,at:u64,count:u64) -> u64:
    header(o,w,RELEASE,0,0,0,count,2)
    i=0
    while i < count:
        put(o,128+i*8,short(s,at+i*2))
        i=i+1
    return 1

def header(o:mutbuf,w:mutbuf,op:u64,nd:u64,na:u64,nr:u64,nv:u64,request:u64) -> u64:
    sequence=get(w,144)+1
    put(w,144,sequence)
    put(w,168,1)
    put(w,184,op)
    put(w,208,request)
    put(o,0,MAGIC)
    put(o,8,get(w,136))
    put(o,16,sequence)
    put(o,24,get(w,160))
    put(o,32,op)
    put(o,40,nd)
    put(o,48,na)
    put(o,56,nr)
    put(o,64,nv)
    put(o,72,request)
    return 0

def finish(o:mutbuf,w:mutbuf,value:u64) -> u64:
    put(o,0,MAGIC)
    put(o,8,get(w,136))
    put(o,16,get(w,144))
    put(o,24,value)
    return 0

def short(s:readbuf,at:u64) -> u64:
    return byte(s,at)|(byte(s,at+1)<<8)

def small(s:readbuf,at:u64) -> u64:
    return short(s,at)|(short(s,at+2)<<16)
'''


def helpers():
    result = []
    for name, typ in (('word', 'readbuf'), ('get', 'mutbuf')):
        result.append('def ' + name + '(b:' + typ + ', at:u64) -> u64:\n    return ' +
                      ' | '.join('(byte(b,at+' + str(i) + ') << ' + str(i * 8) + ')'
                                 for i in range(8)))
    result.append('def put(b:mutbuf,at:u64,value:u64) -> u64:\n' +
                  '\n'.join('    store(b,at+' + str(i) + ',(value >> ' + str(i * 8) + ') & 255)'
                            for i in range(8)) + '\n    return 0')
    result.append('def words(o:mutbuf,w:mutbuf,a:u64,b:u64,c:u64,d:u64,e:u64,f:u64,g:u64,h:u64) -> u64:\n' +
                  '\n'.join('    put(o,get(w,88)+' + str(i * 8) + ',' + chr(97 + i) + ')'
                            for i in range(8)) + '\n    put(w,88,get(w,88)+64)\n    return 0')
    return '\n\n'.join(result)


def emission(data):
    padded = data + bytes((-len(data)) % 64)
    values = struct.unpack('<' + 'Q' * (len(padded) // 8), padded)
    groups = [values[i:i + 128] for i in range(0, len(values), 128)]
    result = ['def emit_policy(o:mutbuf,w:mutbuf) -> u32:\n'
              '    if length(o) < ' + str(len(padded)) + ' or length(w) < 96:\n'
              '        return ABI\n    put(w,88,0)\n' +
              '\n'.join('    emit_part_' + str(i) + '(o,w)' for i in range(len(groups))) +
              '\n    return ' + str(len(data))]
    for index, group in enumerate(groups):
        result.append('def emit_part_' + str(index) + '(o:mutbuf,w:mutbuf) -> u64:\n' +
                      '\n'.join('    words(o,w,' + ','.join(map(str, group[i:i + 8])) + ')'
                                for i in range(0, len(group), 8)) + '\n    return 0')
    return '\n\n'.join(result)


def source():
    policy = program()
    data = table(policy)
    constants = {'MAGIC': MAGIC, 'EMIT_MAGIC': EMIT_MAGIC, 'ABI': ABI,
                 'OUTPUT_BYTES': OUTPUT, 'TABLE_BYTES': len(data),
                 'WORKSPACE_BYTES': 1024 + 8 * max(f.next_slot for f in policy.functions),
                 **OPS}
    parsed = ast.parse(BODY + '\n' + helpers() + '\n' + emission(data) + '\n' + EXCEPTION_BODY)
    class Names(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.copy_location(ast.Constant(constants[node.id]), node) if node.id in constants else node
    return ast.fix_missing_locations(Names().visit(parsed))


def document():
    nodes = source().body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args],
                              node.returns.id) for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name],
                          'params': [builder.param(value) for value in builder.params],
                          'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
                          'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                  'module': 'machine_plan', 'functions': functions})


def main():
    path = ROOT / 'examples/hia_bootstrap/machine_plan.hiaasm'
    path.write_text(render_assembly(document()))
    print(path)


if __name__ == '__main__':
    main()

"""Checked, explicit Agent choices for the finite direct x86-64 backend.

Plans select reviewed realizations. They never supply bytes, remove Core checks,
change effects, or ask the backend to search for a profitable realization. The
preservation claim is conditional on the canonical lowering and encoder.
"""
from __future__ import annotations

from contextvars import ContextVar

_NATIVE_OWNER = ContextVar('hia_machine_plan_native_owner', default=None)

LAYOUT_V1 = "hepta.hia.agent.block-layout.v1"
MACHINE_V2 = "hepta.hia.agent.machine-plan.v2"
MACHINE_V3 = "hepta.hia.agent.machine-plan.v3"
MACHINE_V4 = "hepta.hia.agent.machine-plan.v4"
SCRATCH = frozenset({"r10", "r11"})
VALUE_REGISTERS = ("rbx", "r12", "r13", "r14", "r15")
LEAF_VALUE_REGISTERS = ("r8", "r9")
# Exact finite opcode inventory audited against _Function.operation and its
# helpers. Returning calls, allocation/bulk helpers and buffer.swap (implicit
# r8 scratch) are deliberately excluded. Future opcodes do not inherit access.
LEAF_VALUE_OPS = frozenset({
    "const", "int.add.wrap", "int.add.checked", "int.sub.wrap", "int.sub.checked",
    "int.mul.wrap", "int.mul.checked", "int.div.checked", "int.rem.checked",
    "int.shl.checked", "int.shr.checked", "int.neg.checked", "int.cast",
    "bit.and", "bit.or", "bit.xor", "bit.not", "compare.eq", "compare.ne",
    "compare.lt", "compare.le", "compare.gt", "compare.ge",
    "bool.and", "bool.or", "bool.not", "select",
    "buffer.len", "buffer.load", "buffer.store",
})
VALUE_TYPES = frozenset({f"{sign}{width}" for sign in ("i", "u") for width in (8, 16, 32, 64)}) | {
    "isize", "usize", "bool"}
MOVE_CHOICES = frozenset({"movabs", "mov32_if_exact"})
ALU_CHOICES = frozenset({"imm32", "imm8_if_exact"})
SELECT_CHOICES = frozenset({"branch", "cmov_scalar"})
ALIGNMENTS = frozenset({1, 16, 32, 64})


class MachinePlanRejected(ValueError):
    """A plan exceeds the explicitly reviewed machine-choice surface."""


def _require(ok, message):
    if not ok:
        raise MachinePlanRejected("E_HIA_MACHINE_PLAN: " + message)


def _permutation(order, names, label):
    _require(type(order) is list and len(order) == len(names)
             and all(type(name) is str for name in order)
             and set(order) == set(names), label + " must name every member exactly once")


def _terminal_arguments(term):
    if term["op"] == "ret":
        return term["values"]
    if term["op"] == "jump":
        return term["args"]
    if term["op"] == "branch":
        return [term["cond"], *term["then"]["args"], *term["else"]["args"]]
    return []


def _reference_register_assignment_witness(checked, assignments, *, allow_leaf_registers=False):
    """Independently check caller-supplied scalar register lifetimes.

    Verified Core blocks are closed: every incoming value is an explicit block
    parameter. Intervals therefore stop at each terminator. Edge arguments are
    copied to disjoint temporary stack slots before any target parameter is
    assigned, including backedge permutations. Parameters and dead definitions
    still occupy their definition point, since emitting a dead write can clobber
    a live value. Inputs and outputs at one instruction deliberately interfere;
    no instruction-specific read-before-write assumption is needed here.

    This validates an assignment, not a register allocator or profitability
    search. v3 uses only the fixed callee-saved set. v4 additionally admits
    r8/r9 only in functions whose complete lowering has no returning call or
    implicit write to these registers. All reaching edges retain staged copies.
    """
    _require(type(assignments) is dict, "value_registers must be a function map")
    functions = {fn["name"]: fn for fn in checked.as_dict()["functions"]}
    _require(all(type(name) is str and name in functions for name in assignments),
             "unknown function in value register assignment")
    witnesses = {}
    allowed = VALUE_REGISTERS + (LEAF_VALUE_REGISTERS if allow_leaf_registers else ())
    for name, mapping in assignments.items():
        _require(type(mapping) is dict and all(type(value) is str and type(reg) is str
                 and reg in allowed for value, reg in mapping.items()),
                 "value registers must be explicit assignments admitted by this plan version")
        fn = functions[name]
        leaf_registers = [reg for reg in LEAF_VALUE_REGISTERS if reg in mapping.values()]
        leaf_ops = sorted({op["op"] for block in fn["blocks"] for op in block["ops"]})
        if leaf_registers:
            _require(all(op in LEAF_VALUE_OPS for op in leaf_ops),
                     "caller-clobbered value registers require a leaf opcode whitelist; no calls, swap or allocation/bulk helpers")
            _require(all(p["type"] in VALUE_TYPES | {"readbuf", "mutbuf"} for p in fn["params"])
                     and all(t in VALUE_TYPES for t in fn["returns"]),
                     "leaf registers require scalar/borrowed parameters and scalar returns")
        definitions = {p["name"]: p["type"] for block in fn["blocks"]
                       for p in block["params"] + [p for op in block["ops"] for p in op["out"]]}
        _require(all(value in definitions and definitions[value] in VALUE_TYPES for value in mapping),
                 "register assignment requires an existing integer or boolean SSA value")
        intervals = []
        for block in fn["blocks"]:
            starts = {p["name"]: 0 for p in block["params"]}
            for position, op in enumerate(block["ops"], 1):
                starts.update({p["name"]: position for p in op["out"]})
            ends = dict(starts)
            for position, op in enumerate(block["ops"], 1):
                for value in op["args"]:
                    ends[value] = position
            for value in _terminal_arguments(block["term"]):
                ends[value] = len(block["ops"]) + 1
            by_register = {reg: [] for reg in allowed}
            for value in sorted(starts):
                if value in mapping:
                    row = {"block": block["id"], "value": value, "type": definitions[value],
                           "register": mapping[value], "first": starts[value], "last": ends[value]}
                    intervals.append(row)
                    by_register[mapping[value]].append(row)
            for register, rows in by_register.items():
                rows.sort(key=lambda row: (row["first"], row["value"]))
                for left, right in zip(rows, rows[1:]):
                    _require(left["last"] < right["first"],
                             f"interfering values {name}/{block['id']}: "
                             f"{left['value']} and {right['value']} share {register}")
        witnesses[name] = {"callee_saved_registers": [reg for reg in VALUE_REGISTERS if reg in mapping.values()],
                           "intervals": intervals}
        if allow_leaf_registers:
            witnesses[name].update(caller_clobbered_leaf_registers=leaf_registers,
                                   leaf_opcode_inventory=leaf_ops if leaf_registers else [])
    return {"rule": "closed-block inclusive lifetimes; all edge sources staged before target writes",
            "functions": witnesses}


def _reference_validate_plan(checked, plan):
    """Freeze a plan against an already reverified immutable Core document."""
    _require(type(plan) is dict, "plan must be an object")
    # Capture exact built-in JSON data before inspecting any plan field. The
    # existing Core decoder rejects subclasses/hooks, cycles and oversized
    # trees, then returns a detached bounded snapshot. Checking caller-owned
    # values and only deepcopying afterwards lets copying hooks or concurrent
    # mutation change the plan after its register lifetimes were checked.
    from .hia_program import HIAProgramRejected, _decode
    try:
        plan, _ = _decode(plan)
    except HIAProgramRejected as exc:
        raise MachinePlanRejected("E_HIA_MACHINE_PLAN: plan requires bounded plain JSON data") from exc
    schema = plan.get("schema")
    _require(type(schema) is str and schema in {LAYOUT_V1, MACHINE_V2, MACHINE_V3, MACHINE_V4}, "unknown plan schema")
    fields = {"schema", "core_sha256", "block_order"}
    if schema in {MACHINE_V2, MACHINE_V3, MACHINE_V4}:
        fields |= {"function_order", "scratch_registers", "instruction_selection", "function_alignment"}
    if schema in {MACHINE_V3, MACHINE_V4}:
        fields.add("value_registers")
    _require(set(plan) == fields, "plan has missing or unreviewed fields")
    _require(plan["core_sha256"] == checked.sha256, "plan belongs to a different Core")
    functions = {fn["name"]: fn for fn in checked.as_dict()["functions"]}
    orders = plan["block_order"]
    _require(type(orders) is dict and (bool(orders) or schema in {MACHINE_V2, MACHINE_V3, MACHINE_V4}), "invalid block order map")
    for name, order in orders.items():
        _require(type(name) is str and name in functions, "unknown function in block order")
        _permutation(order, [block["id"] for block in functions[name]["blocks"]], "block order")
    if schema in {MACHINE_V2, MACHINE_V3, MACHINE_V4}:
        _permutation(plan["function_order"], functions, "function order")
        registers = plan["scratch_registers"]
        _require(type(registers) is dict and set(registers) == SCRATCH
                 and all(type(value) is str for value in registers.values())
                 and set(registers.values()) == SCRATCH,
                 "scratch assignment must bijectively rename only r10 and r11")
        choices = plan["instruction_selection"]
        choice_fields = {"move_immediate", "alu_immediate"} | ({"scalar_select"} if schema in {MACHINE_V3, MACHINE_V4} else set())
        _require(type(choices) is dict and set(choices) == choice_fields,
                 "instruction choices must be explicit and complete")
        _require(type(choices["move_immediate"]) is str and choices["move_immediate"] in MOVE_CHOICES,
                 "unreviewed immediate move encoding")
        _require(type(choices["alu_immediate"]) is str and choices["alu_immediate"] in ALU_CHOICES,
                 "unreviewed immediate arithmetic encoding")
        _require(type(plan["function_alignment"]) is int and plan["function_alignment"] in ALIGNMENTS,
                 "unreviewed function alignment")
        if schema in {MACHINE_V3, MACHINE_V4}:
            _require(type(choices["scalar_select"]) is str and choices["scalar_select"] in SELECT_CHOICES,
                     "unreviewed scalar select encoding")
            if schema == MACHINE_V4:
                register_assignment_witness(checked, plan["value_registers"], allow_leaf_registers=True)
            else:
                register_assignment_witness(checked, plan["value_registers"])
    return plan  # This exact detached snapshot was checked and is emitted.


def _reference_code_options(plan):
    if plan is None or plan["schema"] == LAYOUT_V1:
        return {}
    return {"scratch_registers": dict(plan["scratch_registers"]),
            "move_immediate": plan["instruction_selection"]["move_immediate"],
            "alu_immediate": plan["instruction_selection"]["alu_immediate"]}


def _reference_preservation_checks(plan, checked=None):
    """Separate claims, with no promotion to whole-backend refinement."""
    checks = [{"choice": "block_layout", "checked": True,
               "rule": "exact block permutations; every terminator transfers explicitly"}]
    if plan["schema"] in {MACHINE_V2, MACHINE_V3, MACHINE_V4}:
        checks.extend([
            {"choice": "scratch_registers", "checked": True,
             "rule": "bijection on explicit caller-clobbered r10/r11; implicit ISA and ABI registers fixed"},
            {"choice": "instruction_selection", "checked": True,
             "rule": "mov32 only for exact u32; imm8 only for exact sign-extended i8; flags preserved"},
            {"choice": "function_layout", "checked": True,
             "rule": "exact function permutation, symbol relocations retained, NOPs only between functions"},
        ])
    if plan["schema"] in {MACHINE_V3, MACHINE_V4}:
        _require(checked is not None and plan["core_sha256"] == checked.sha256,
                 "register preservation witness requires the exact verified Core")
        checks.extend([
            {"choice": "value_registers", "checked": True,
             "rule": "noninterfering scalar lifetimes; staged edge copies; all used callee-saved registers saved/restored",
             "witness": (register_assignment_witness(checked, plan["value_registers"], allow_leaf_registers=True)
                         if plan["schema"] == MACHINE_V4 else register_assignment_witness(checked, plan["value_registers"]))},
            {"choice": "scalar_select", "checked": True,
             "rule": "explicit branch or register-only CMOV; all operands already defined scalars; MOV loads preserve TEST flags"},
        ])
        if plan["schema"] == MACHINE_V4:
            checks.append({"choice": "caller_clobbered_leaf_values", "checked": True,
                "rule": "r8/r9 only; exact leaf opcode inventory; no returning call; no implicit r8/r9 scratch; scalar values; inclusive lifetimes; staged entry/edge copies",
                "trap_rule": "all trap paths call abort then UD2 and have no returning continuation"})
    return checks


# Operator-only selection.  No field of the caller's plan selects an image.
def _native_owner():
    import os
    from .hia_machine_plan_native import SELECTOR, installed_machine_plan
    captured = _NATIVE_OWNER.get()
    if captured is not None:
        return captured
    path = os.environ.get(SELECTOR)
    return installed_machine_plan(path) if path else None


def validate_plan(checked, plan):
    selected = _native_owner()
    if selected is None:
        return _reference_validate_plan(checked, plan)
    token = _NATIVE_OWNER.set(selected)
    try:
        return selected.validate(checked, plan)
    finally:
        _NATIVE_OWNER.reset(token)


def register_assignment_witness(checked, assignments, *, allow_leaf_registers=False):
    selected = _native_owner()
    if selected is None:
        return _reference_register_assignment_witness(
            checked, assignments, allow_leaf_registers=allow_leaf_registers)
    token = _NATIVE_OWNER.set(selected)
    try:
        return selected.witness(checked, assignments, allow_leaf_registers=allow_leaf_registers)
    finally:
        _NATIVE_OWNER.reset(token)


def code_options(plan):
    selected = _native_owner()
    if selected is None:
        return _reference_code_options(plan)
    token = _NATIVE_OWNER.set(selected)
    try:
        return selected.code_options(plan)
    finally:
        _NATIVE_OWNER.reset(token)


def preservation_checks(plan, checked=None):
    selected = _native_owner()
    if selected is None:
        return _reference_preservation_checks(plan, checked)
    token = _NATIVE_OWNER.set(selected)
    try:
        return selected.preservation_checks(plan, checked)
    finally:
        _NATIVE_OWNER.reset(token)


# Used only to distinguish the original public continuation from a caller's
# explicitly replaced hook at the HIA-issued GLOBAL observation boundary.
_NATIVE_PUBLIC_WITNESS = register_assignment_witness


def native_implementation_identity():
    selected = _native_owner()
    if selected is None:
        return b''
    return (b'machine-plan-v2\0' + selected.image_sha256.encode() + b'\0' +
            selected.admitted_source_sha256.encode())

